CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('RENTER','ADMIN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE rental_kind AS ENUM ('PARCEL','FULL_REGION'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE rental_status AS ENUM ('PENDING','ACTIVE','ENDED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE invoice_status AS ENUM ('OPEN','PAID','VOID'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE payment_status AS ENUM ('PENDING','CONFIRMED','MANUAL_REVIEW','FAILED','REFUNDED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL DEFAULT 'RENTER', display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sl_identities (avatar_id uuid PRIMARY KEY, user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, canonical_username text NOT NULL UNIQUE, display_name text NOT NULL, verified_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), avatar_id uuid NOT NULL, canonical_username text NOT NULL, otp_digest char(64) NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5), last_sent_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_challenge_lookup ON login_challenges(canonical_username, created_at DESC);
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash char(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (scope text NOT NULL, subject_hash char(64) NOT NULL, window_start timestamptz NOT NULL, hits int NOT NULL CHECK(hits>0), PRIMARY KEY(scope,subject_hash,window_start));
CREATE TABLE IF NOT EXISTS bot_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), avatar_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('LOGIN_OTP','NOTICE')), payload jsonb NOT NULL, challenge_id uuid REFERENCES login_challenges(id) ON DELETE CASCADE, expires_at timestamptz, available_at timestamptz NOT NULL DEFAULT now(), attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 8), claimed_at timestamptz, sent_at timestamptz, dead_lettered_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS bot_outbox_pending ON bot_outbox(available_at) WHERE sent_at IS NULL;
CREATE TABLE IF NOT EXISTS simulation_mailbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), avatar_id uuid NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, region_name text NOT NULL, grid_x int, grid_y int, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), slug text NOT NULL UNIQUE, name text NOT NULL, kind rental_kind NOT NULL, description text NOT NULL, area_sqm int NOT NULL CHECK(area_sqm>0), prims int NOT NULL CHECK(prims>=0), published boolean NOT NULL DEFAULT false, hero_gradient text NOT NULL DEFAULT 'violet', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pricing (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE, weekly_linden int NOT NULL CHECK(weekly_linden>0), setup_linden int NOT NULL DEFAULT 0 CHECK(setup_linden>=0), stripe_currency char(3) NOT NULL DEFAULT 'usd', stripe_weekly_minor int NOT NULL CHECK(stripe_weekly_minor>0), stripe_setup_minor int NOT NULL DEFAULT 0 CHECK(stripe_setup_minor>=0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_pricing ON pricing(listing_id) WHERE active;
CREATE TABLE IF NOT EXISTS rentals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id), user_id uuid NOT NULL REFERENCES users(id), status rental_status NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
DROP INDEX IF EXISTS one_active_rental;
CREATE UNIQUE INDEX IF NOT EXISTS one_live_rental ON rentals(listing_id) WHERE status IN ('PENDING','ACTIVE');
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rental_id uuid REFERENCES rentals(id), listing_id uuid NOT NULL REFERENCES listings(id), user_id uuid NOT NULL REFERENCES users(id), status invoice_status NOT NULL DEFAULT 'OPEN', amount_linden int CHECK(amount_linden IS NULL OR amount_linden>0), amount_minor int CHECK(amount_minor IS NULL OR amount_minor>0), currency char(3), due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK((amount_linden IS NOT NULL)::int + (amount_minor IS NOT NULL)::int = 1));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), provider text NOT NULL CHECK(provider IN ('STRIPE','LINDEN','SIMULATION')), provider_reference text NOT NULL, amount_linden int, amount_minor int, currency char(3), expected_amount_linden int, expected_amount_minor int, expected_currency char(3), status payment_status NOT NULL, reconciliation_note text, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_reference), CHECK((provider='LINDEN' AND amount_linden IS NOT NULL AND amount_minor IS NULL) OR (provider IN ('STRIPE','SIMULATION') AND amount_minor IS NOT NULL AND amount_linden IS NULL)));
CREATE TABLE IF NOT EXISTS stripe_events (event_id text PRIMARY KEY, event_type text NOT NULL, payload_sha256 char(64) NOT NULL, processing_status text NOT NULL CHECK(processing_status IN ('RECEIVED','PROCESSED','IGNORED','MANUAL_REVIEW','FAILED')), processing_note text, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stripe_checkout_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), generation int NOT NULL DEFAULT 1, idempotency_key text NOT NULL UNIQUE, session_id text UNIQUE, session_url text, status text NOT NULL CHECK(status IN ('CREATING','OPEN','COMPLETED','EXPIRED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(invoice_id,generation));
CREATE TABLE IF NOT EXISTS terminals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES listings(id), object_id uuid NOT NULL UNIQUE, owner_id uuid NOT NULL, shard text NOT NULL, secret_ciphertext text NOT NULL, enabled boolean NOT NULL DEFAULT true, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS terminal_nonces (terminal_id uuid NOT NULL REFERENCES terminals(id) ON DELETE CASCADE, nonce text NOT NULL, seen_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(terminal_id,nonce));
CREATE TABLE IF NOT EXISTS terminal_payment_events (terminal_id uuid NOT NULL REFERENCES terminals(id), event_id text NOT NULL, payer_avatar_id uuid NOT NULL, amount_linden int NOT NULL CHECK(amount_linden>0), expected_amount_linden int NOT NULL CHECK(expected_amount_linden>0), status payment_status NOT NULL, payment_id uuid REFERENCES payments(id), resolution_note text, resolved_by uuid REFERENCES users(id), resolved_at timestamptz, raw_body_sha256 char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(terminal_id,event_id));
CREATE TABLE IF NOT EXISTS terminal_outbound_events (id bigserial PRIMARY KEY, terminal_id uuid NOT NULL REFERENCES terminals(id), kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS terminal_nonce_retention ON terminal_nonces(seen_at);
CREATE INDEX IF NOT EXISTS terminal_outbound_retention ON terminal_outbound_events(created_at);
CREATE TABLE IF NOT EXISTS bot_health (worker_id text PRIMARY KEY, mode text NOT NULL, adapter_connected boolean NOT NULL, last_db_ok_at timestamptz NOT NULL, heartbeat_at timestamptz NOT NULL, last_error text);
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, actor_user_id uuid REFERENCES users(id), action text NOT NULL, target_type text NOT NULL, target_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
